def mode(d, ms): return {"name": "mode", "type": "str", "required": False, "default": d, "meaning": ("Must be \"background\": this command has no verified ui mode." if ms == ["background"] else "Must be \"ui\": this command only shows something on screen." if ms == ["ui"] else "\"ui\" or \"background\"; use one of this command's modes.")}
PATH = {"name": "path", "type": "str", "required": True, "default": None, "meaning": "An absolute path, or one starting with ~."}
TO_F = {"name": "to_folder", "type": "str", "required": True, "default": None, "meaning": "The folder to put it in, which must exist."}
LIMIT = {"name": "limit", "type": "int", "required": False, "default": 100, "meaning": "The most items to return."}
FIELDS = {"name": "fields", "type": "str | list | None", "required": False, "default": None, "meaning": "Fields to return, as a comma-separated string or a list; adds created_date if asked."}
V = {"name": "ValueError", "when": "an argument is invalid or mode isn't \"ui\" or \"background\""}
U = {"name": "UIError", "when": "a named element never appeared, or the change wasn't seen in time"}
S = {"name": "StateBlocked", "when": "a name is being edited, a dialog holds text, or another app came to the front; nothing is changed"}
NF = {"name": "NotFound", "when": "nothing exists at the path, or the folder is missing; nothing is changed"}
AE = {"name": "AlreadyExists", "when": "the new path is taken; nothing is overwritten"}
OUT = {"name": "OutsideAllowedRoot", "when": "FINDER_ALLOWED_ROOT is set and a path is outside it; nothing is done"}
