PREU = "For ui mode, the program has Accessibility, and Automation for System Events."
PRER = "The program can read the folder; macOS may ask once for protected folders."
ITEM = {"type": "object", "fields": ["name", "path", "kind", "size", "modified_date"]}
READ = {"type": "list", "fields": ["name", "path", "kind", "size", "modified_date"], "optional_fields": ["created_date"]}
def cmd(name, desc, args, ms, default, req, eff, pre, post, ret, errs, gaps, confirm=None):
    c = {"name": name, "description": desc, "args": args, "modes": {"verified": ms, "default": default}, "example_requests": req, "effects": eff, "destructive": confirm is not None, "precondition": pre, "postcondition": post, "returns": ret, "errors": errs}
    if confirm: c["confirm"] = confirm
    c["known_gaps"] = gaps
    return c
BOTH, BG, UI = ["ui", "background"], ["background"], ["ui"]
cmds = [
 cmd("file_list", "Lists the files and folders directly in a folder, by name, leaving out hidden ones.", [{"name": "folder", "type": "str", "required": True, "default": None, "meaning": "An absolute path, or one starting with ~."}, LIMIT, FIELDS, mode("background", BG)], BG, "background", ["What's in my Downloads folder?", "List the files in Invoices", "Show me this folder"], "read_only", PRER, "Nothing is changed.", READ, [V, U, NF, OUT, NSB], [M, ROOT]),
 cmd("file_find", "Finds files and folders under a folder by name or pattern, newest first.", [{"name": "query", "type": "str", "required": True, "default": None, "meaning": "Text in the name, ignoring case, or a pattern such as *.pdf."}, {"name": "folder", "type": "str", "required": False, "default": "~", "meaning": "Where to look, including subfolders."}, LIMIT, FIELDS, mode("background", BG)], BG, "background", ["Find my PDFs in Downloads", "Where is the invoice file?", "Search for files called budget"], "read_only", PRER, "Nothing is changed.", READ, [V, U, NF, OUT, NSB], [M, ROOT, "Hidden folders and ~/Library are skipped."]),
 cmd("file_info", "Returns the name, kind, size and dates of one file or folder.", [PATH, FIELDS, mode("background", BG)], BG, "background", ["How big is this file?", "When was the report last changed?", "Get info on this folder"], "read_only", PRER, "Nothing is changed.", READ | {"type": "object"}, [V, U, NF, OUT, NSB], [M, ROOT]),
 cmd("folder_create", "Makes a new folder whose parent already exists.", [PATH, mode("ui", BOTH)], BOTH, "ui", ["Make a folder called Invoices in Documents", "Create a new folder for the trip", "Add a Photos folder here"], "non_idempotent", PREU, "The folder exists and is empty.", ITEM, [V, U, S, NF, AE, OUT], [M, ROOT, EN, BIG]),
 cmd("file_copy", "Copies a file or folder into another folder, keeping its name.", [PATH, TO_F, mode("ui", BOTH)], BOTH, "ui", ["Copy the report to Archive", "Put a copy of this file in Documents", "Duplicate this folder into Backups"], "non_idempotent", PREU, "The copy exists with the same content, and the original is unchanged.", ITEM, [V, U, S, NF, AE, OUT], [M, ROOT, EN, BIG]),
 cmd("file_move", "Moves a file or folder into another folder, keeping its name.", [PATH, TO_F, mode("ui", BOTH)], BOTH, "ui", ["Move the report to Archive", "Put this PDF in Invoices", "Move this folder into Documents"], "non_idempotent", PREU, "It is in the new folder with the same content, and gone from the old one.", ITEM, [V, U, S, NF, AE, OUT], [M, ROOT, EN, BIG]),
 cmd("file_rename", "Renames a file or folder in the same place.", [PATH, {"name": "to", "type": "str", "required": True, "default": None, "meaning": "The new name, without / or line breaks."}, mode("ui", BOTH)], BOTH, "ui", ["Rename this file to report.pdf", "Call this folder Old", "Change the name of the invoice file"], "non_idempotent", PREU, "It has the new name and the same content.", ITEM, [V, U, S, NF, AE, OUT], [M, ROOT, EN, BIG, "Finder can store a pasted name in a different Unicode form."]),
 cmd("file_trash", "Moves a file or folder to the Trash, from where it can be put back.", [PATH, mode("ui", BOTH)], BOTH, "ui", ["Move this file to the Trash", "Bin the old report", "Trash this folder"], "non_idempotent", PREU, "It is in the Trash, and nothing is permanently deleted.", {"type": "object", "fields": ["name", "path", "kind", "size", "modified_date", "trashed"]}, [V, U, S, NF, OUT], [M, ROOT, EN, BIG, "Emptying the Trash and permanent delete are left out on purpose."], "Move <path> to the Trash?"),
 cmd("file_reveal", "Shows a file or folder selected in a Finder window, changing nothing on disk.", [PATH, mode("ui", UI)], UI, "ui", ["Show me this file in Finder", "Reveal the report", "Where is this file? Show me"], "idempotent", PREU, "Finder shows it selected, and nothing on disk changed.", {"type": "object", "fields": ["name", "path", "kind", "size", "modified_date", "revealed"]}, [V, U, S, NF, OUT, NSU], [M, ROOT, EN, BIG, "What it shows was read back through Finder's window, which isn't independent of Finder."]),
 cmd("folder_open", "Shows a folder in a Finder window, changing nothing on disk.", [PATH, mode("ui", UI)], UI, "ui", ["Open my Documents folder", "Show me the Invoices folder", "Open this folder in Finder"], "idempotent", PREU, "Finder shows the folder, and nothing on disk changed.", {"type": "object", "fields": ["name", "path", "kind", "size", "modified_date", "opened"]}, [V, U, S, NF, OUT, NSU], [M, ROOT, EN, "What it shows was read back through Finder's window, which isn't independent of Finder."]),
]
PATHS = {"name": "paths", "type": "list", "required": True, "default": None, "meaning": "Absolute paths (or starting with ~) of items in the same folder."}
UIM = {"name": "mode", "type": "str", "required": False, "default": "ui", "meaning": "Must be \"ui\": Finder has no scripting or file API that is the same action."}
NSX = {"name": "NotSupported", "when": "mode is \"background\": there is no background mode for this command"}
MORE = [
 cmd("file_compress", "Makes a .zip of one or more items in the same folder with File > Compress; the items stay.", [PATHS, UIM], UI, "ui", ["Zip up this folder", "Compress these three files", "Make a zip of the report"], "non_idempotent", PREU, "One item gives name.zip and several give Archive.zip, next to them.", ITEM, [V, U, S, NF, AE, OUT, NSX], [M, ROOT, EN, "Names are those Finder gives; Archive.zip already there raises AlreadyExists.", "Zip names are written by Archive Utility in UTF-8 without the zip's UTF-8 flag."]),
 cmd("file_extract", "Opens a .zip so Archive Utility expands it next to itself; the .zip stays.", [PATH, UIM], UI, "ui", ["Unzip this file", "Extract the archive", "Open up the zip I downloaded"], "non_idempotent", PREU, "The zip's contents are next to it.", {"type": "object", "fields": ["zip", "items"]}, [V, U, S, NF, OUT, NSX], [M, ROOT, EN, "Only .zip files were tested; where Archive Utility puts a clashing name is its own choice."]),
 cmd("file_duplicate", "Duplicates an item in its own folder with File > Duplicate.", [PATH, UIM], UI, "ui", ["Duplicate this file", "Make a copy of the folder here", "Copy this document in place"], "non_idempotent", PREU, "A copy named by Finder, such as \"name copy\", is next to it.", ITEM, [V, U, S, NF, OUT, NSX], [M, ROOT, EN]),
 cmd("file_put_back", "Puts an item in the Trash back where it came from with File > Put Back.", [{"name": "name", "type": "str", "required": True, "default": None, "meaning": "The item's name in the Trash."}, UIM], UI, "ui", ["Restore the file I deleted", "Put back the report from the Trash", "Undo deleting this folder"], "non_idempotent", PREU, "The item is back at its old place and not in the Trash.", {"type": "object", "fields": ["name", "put_back"]}, [V, U, S, NF, NSX], [M, EN, "Finder's own scripting opens the Trash window, because Go to Folder won't show it.", "Only items trashed through Finder were tested; Finder needs to know where they came from.", "There is no allowed-folder check on where it goes back to."]),
 cmd("file_add_tag", "Adds a tag to an item in its Get Info window.", [PATH, {"name": "tag", "type": "str", "required": True, "default": None, "meaning": "The tag name, such as Red or Project X; one line, no commas."}, UIM], UI, "ui", ["Tag this file Red", "Add the tag Invoices to these documents", "Label the folder Project X"], "idempotent", PREU, "The item has the tag, and its other tags stay.", {"type": "object", "fields": ["name", "path", "kind", "size", "modified_date", "tags"]}, [V, U, S, NF, AE, OUT, NSX], [M, ROOT, EN, "macOS 15.6.1's File menu has no Tags… item, so this uses Get Info.", "A new tag name is created by Finder with no colour."]),
 cmd("folder_new_with_selection", "Moves items in the same folder into a new folder there with File > New Folder with Selection.", [PATHS, {"name": "name", "type": "str", "required": True, "default": None, "meaning": "The new folder's name; one name without / or line breaks."}, UIM], UI, "ui", ["Put these files in a new folder called Receipts", "Group the selected photos into a folder", "Make a folder with these three documents"], "non_idempotent", PREU, "The new folder holds the items and they are gone from where they were.", {"type": "object", "fields": ["name", "path", "kind", "size", "modified_date", "items"]}, [V, U, S, NF, AE, OUT, NSX], [M, ROOT, EN, "It needs at least two items."]),
 cmd("file_make_alias", "Makes a Finder alias of an item, next to it, with File > Make Alias.", [PATH, UIM], UI, "ui", ["Make an alias of this folder", "Create a shortcut to the report", "Add an alias of the app here"], "non_idempotent", PREU, "An alias named by Finder (\"name alias\") is next to the item and opens it.", {"type": "object", "fields": ["name", "path", "original"]}, [V, U, S, NF, OUT, NSX], [M, ROOT, EN, "Finder names the alias; a clashing name gets a number."]),
 cmd("file_set_locked", "Locks a file or folder (Get Info > Locked) so it can't be changed, or unlocks it.", [PATH, {"name": "locked", "type": "bool", "required": False, "default": True, "meaning": "True to lock, False to unlock."}, mode("ui", BOTH)], BOTH, "ui", ["Lock this file so it can't be edited", "Unlock the report", "Protect this folder from changes"], "idempotent", PREU, "The item's lock flag is as asked; its content is unchanged.", {"type": "object", "fields": ["name", "path", "kind", "size", "modified_date", "locked", "changed"]}, [V, U, S, NF, OUT], [M, ROOT, EN, "ui mode ticks or clears Locked in the item's Get Info window and closes it; background sets the file's own lock flag (the one Finder's Locked sets) through the macOS file APIs.", "Added overnight at the end of the file and tested on its own."]),
 cmd("file_open_with", "Opens a file with a chosen app from Finder's File > Open With menu, by the app's name there.", [PATH, {"name": "app", "type": "str", "required": True, "default": None, "meaning": "The app's name as Open With shows it, such as TextEdit or Preview (without \" (default)\")."}, UIM], UI, "ui", ["Open this PNG in ColorSync Utility", "Open notes.txt with TextEdit", "Open the image with Preview"], "non_idempotent", PREU, "The app is in front with a window showing the file; the file is unchanged.", {"type": "object", "fields": ["name", "path", "kind", "size", "modified_date", "app", "default"]}, [V, U, S, {"name": "NotFound", "when": "there's no file at path, or Open With doesn't offer that app for it (the error lists what it offers)"}, OUT, NSX], [M, ROOT, EN, "The app must show the file as its window's document; TextEdit, Preview and ColorSync Utility do, but Safari and Script Editor don't, so with them it raises UIError after the file has opened.", "Added overnight at the end of the file and tested on its own."]),
]
